text:
{
 "lead": {
  "es": "気象業務法《きしょうぎょうむほう》と水防法《すいぼうほう》をかえる法律《ほうりつ》です。洪水《こうずい》（大雨《おおあめ》で川《かわ》の水《みず》があふれること）を、特別警報《とくべつけいほう》（とくに大《おお》きな災害《さいがい》のおそれがあるときの知《し》らせ）に加《くわ》えます。高潮《たかしお》（台風《たいふう》などで海《うみ》の水面《すいめん》が高《たか》くなること）の水《みず》の高《たか》さをしめした予報《よほう》や警報《けいほう》、川《かわ》があふれる危険《きけん》がせまったときの知《し》らせ方《かた》などを決《き》めます。",
  "hs": "洪水《こうずい》を特別警報の対象に加え、高潮（台風などで海面が高くなること）の水位を示した予報・警報や、氾濫《はんらん》（川の水があふれること）の危険が迫《せま》ったときの通報・周知（広く知らせること）の仕組みなどを定めるため、気象業務法と水防法を改正する法律です。"
 },
 "facts/0/text": {
  "es": "気象庁《きしょうちょう》の特別警報《とくべつけいほう》に、洪水《こうずい》を加《くわ》えます。国土交通大臣《こくどこうつうだいじん》や都道府県知事《とどうふけんちじ》が決《き》めた川《かわ》で、洪水《こうずい》の特別警報《とくべつけいほう》を出《だ》すとき、気象庁《きしょうちょう》は、国土交通大臣《こくどこうつうだいじん》や都道府県知事《とどうふけんちじ》に、川《かわ》のようすを教《おし》えてほしいとたのめます。たのまれた側《がわ》は、教《おし》えなければなりません。",
  "hs": "気象庁の特別警報の対象に洪水《こうずい》を加えます。国土交通大臣や都道府県知事が指定した河川で洪水《こうずい》の特別警報をする場合、気象庁は国土交通大臣や関係する都道府県知事に、河川の状況《じょうきょう》の情報を出すよう求めることができます。求められた側は、情報を出さなければなりません。"
 },
 "facts/1/text": {
  "es": "国土交通大臣《こくどこうつうだいじん》が決《き》めた海岸《かいがん》について、気象庁《きしょうちょう》は、国土交通大臣《こくどこうつうだいじん》や都道府県知事《とどうふけんちじ》といっしょに、高潮《たかしお》の予報《よほう》と警報《けいほう》を出《だ》さなければなりません。この予報《よほう》と警報《けいほう》は、水《みず》の高《たか》さをしめし、水防《すいぼう》（水《みず》の害《がい》をふせぐ活動《かつどう》）に使《つか》えるものにします。",
  "hs": "国土交通大臣が指定した海岸について、気象庁は国土交通大臣・都道府県知事と共同して、水位を示した高潮の予報と警報をしなければなりません。これは水防活動（水害を防ぐ活動）に使うためのものです。"
 },
 "facts/2/text": {
  "es": "外国《がいこく》の会社《かいしゃ》など（外国法人《がいこくほうじん》等《とう》）が、天気《てんき》などの予報《よほう》の仕事《しごと》のゆるし（許可《きょか》）をもらうときは、日本《にほん》にいる代表者《だいひょうしゃ》などを決《き》めなければなりません。許可《きょか》をもらった人《ひと》（外国《がいこく》の会社《かいしゃ》などは日本《にほん》の代表者《だいひょうしゃ》など）がどこにいるか分《わ》からないときは、かんたんな手続《てつづ》きで許可《きょか》をとり消《け》せるしくみを作《つく》ります。気象業務法《きしょうぎょうむほう》などのきまりをやぶった人《ひと》の名前《なまえ》などを、発表《はっぴょう》できるしくみも作《つく》ります。",
  "hs": "外国法人等が予報業務（天気などの予報の仕事）の許可を受ける場合は、国内代表者等を定めなければなりません。許可を受けた者（外国法人等は国内代表者等）の所在が確かめられないときに簡単な手続きで許可を取り消せる制度と、気象業務法等に違反《いはん》した者の氏名などを公表できる制度をつくります。"
 },
 "facts/3/text": {
  "es": "国土交通大臣《こくどこうつうだいじん》は、高潮《たかしお》で国《くに》全体《ぜんたい》のくらしやお金《かね》の動《うご》きに大《おお》きなひがいが出《で》るおそれがある海岸《かいがん》を決《き》めます。その海岸《かいがん》で高潮《たかしお》のおそれがあるときは、国土交通大臣《こくどこうつうだいじん》は気象庁《きしょうちょう》長官《ちょうかん》や都道府県知事《とどうふけんちじ》といっしょに、水《みず》の高《たか》さをしめして、すぐに水防《すいぼう》管理者《かんりしゃ》（水《みず》の害《がい》をふせぐ役目《やくめ》の人《ひと》）などに知《し》らせます。ひつようなら、テレビや新聞《しんぶん》などの力《ちから》もかりて、みんなに知《し》らせなければなりません。",
  "hs": "国土交通大臣は、高潮で国民経済上の重大な損害が出るおそれがあるとして指定した海岸で高潮のおそれがあるとき、気象庁長官と都道府県知事と共同して、水位を示してすぐに水防管理者等（水害を防ぐ活動の責任者など）に通知しなければなりません。必要に応じて報道機関の協力を求め、広く知らせなければなりません。"
 },
 "facts/4/text": {
  "es": "川《かわ》などを管理《かんり》する人《ひと》（河川管理者《かせんかんりしゃ》等《とう》）は、浸水《しんすい》想定《そうてい》区域《くいき》（水《みず》につかると考《かんが》えられる場所《ばしょ》）で、川《かわ》があふれるとても大《おお》きな危険《きけん》がせまっているときは、すぐに都道府県知事《とどうふけんちじ》などに知《し》らせなければなりません。知《し》らせを受《う》けた都道府県知事《とどうふけんちじ》などは、かなりのひがいが出《で》るおそれがあるときは、すぐに水防《すいぼう》管理者《かんりしゃ》などと気象庁《きしょうちょう》長官《ちょうかん》に知《し》らせます。ひつようなら、テレビや新聞《しんぶん》などの力《ちから》もかりて、みんなに知《し》らせなければなりません。",
  "hs": "河川管理者等は、浸水《しんすい》想定区域（水につかると想定される区域）で氾濫《はんらん》による著しい危険が迫《せま》っているときは、すぐに関係する都道府県知事等に通報しなければなりません。通報を受けた都道府県知事等は、相当な損害のおそれがあるときは、すぐに水防管理者等と気象庁長官に通知し、必要に応じて報道機関の協力を求めて、広く知らせなければなりません。"
 },
 "facts/5/text": {
  "es": "一部《いちぶ》をのぞき、この法律《ほうりつ》が公布《こうふ》（国民《こくみん》に知《し》らせること）された日《ひ》から6か月《げつ》いないの、政令《せいれい》（内閣《ないかく》が決《き》めるきまり）で決《き》める日《ひ》から始《はじ》まります。",
  "hs": "一部の規定を除き、公布（法律を国民に知らせること）の日から6か月以内で、政令（内閣が定めるきまり）で定める日から施行《しこう》（実際に使われ始めること）します。"
 },
 "more/reason/text": {
  "es": "内閣《ないかく》は、水《みず》による災害《さいがい》のひがいをへらすため、洪水《こうずい》の特別警報《とくべつけいほう》や、国土交通大臣《こくどこうつうだいじん》などがいっしょに出《だ》す高潮《たかしお》の予報《よほう》・警報《けいほう》を作《つく》り、川《かわ》を管理《かんり》する人《ひと》などが川《かわ》があふれそうなことなどを知《し》らせるようにする必要《ひつよう》があるためとしている。また、情報通信《じょうほうつうしん》の技術《ぎじゅつ》が進《すす》んだことをふまえ、予報《よほう》を使《つか》う人《ひと》を守《まも》るため、外国《がいこく》の会社《かいしゃ》などが行《おこな》う予報《よほう》の仕事《しごと》の許可《きょか》のきまりなどを整《ととの》える必要《ひつよう》があるためとしている。",
  "hs": "内閣は、水災（水による災害）の被害《ひがい》を減らすため、洪水《こうずい》の特別警報の創設、国土交通大臣などが共同で行う高潮の予報・警報の創設、河川管理者などによる氾濫《はんらん》などの通報の実施《じっし》などの措置《そち》をとり、情報通信技術の進展をふまえ、予報業務の利用者を守るため、外国法人などが行う予報業務の許可の規定などを整える必要があるためとしている。"
 },
 "more/who/text": {
  "es": "気象庁《きしょうちょう》、国土交通大臣《こくどこうつうだいじん》、都道府県知事《とどうふけんちじ》、川《かわ》などを管理《かんり》する人《ひと》（河川管理者《かせんかんりしゃ》等《とう》）、水防計画《すいぼうけいかく》で決《き》められた水防《すいぼう》管理者《かんりしゃ》など（水《みず》の害《がい》をふせぐ役目《やくめ》の人《ひと》）、予報《よほう》の仕事《しごと》の許可《きょか》を受《う》けたい外国《がいこく》の会社《かいしゃ》など（外国法人《がいこくほうじん》等《とう》）",
  "hs": "気象庁、国土交通大臣、都道府県知事、河川管理者等、水防計画で定める水防管理者等（水害を防ぐ活動の責任者など）、予報業務の許可を受けようとする外国法人等"
 },
 "more/committee/text": {
  "es": "衆議院《しゅうぎいん》と参議院《さんぎいん》の国土交通委員会《こくどこうつういいんかい》で話《はな》し合《あ》われた。参議院《さんぎいん》では、洪水《こうずい》の特別警報《とくべつけいほう》を作《つく》るわけとその効果《こうか》、洪水《こうずい》の特別警報《とくべつけいほう》など防災《ぼうさい》の気象情報《きしょうじょうほう》を正《ただ》しく伝《つた》え、みんなに知《し》らせる必要性《ひつようせい》、予報《よほう》の仕事《しごと》のきまりをきちんと守《まも》らせる方法《ほうほう》などについて、質問《しつもん》があった。どちらも全員《ぜんいん》が賛成《さんせい》して、もとの案《あん》のまま可決《かけつ》した。",
  "hs": "衆議院・参議院の国土交通委員会で審査《しんさ》された。参議院では、洪水《こうずい》特別警報をつくる背景と効果、洪水《こうずい》特別警報などの防災気象情報を的確に伝え、周知する（広く知らせる）必要性、予報業務の規制の実効性を確保する方策などについて質疑があった。どちらも全会一致《ぜんかいいっち》（全員が賛成）で原案どおり可決した。"
 }
}
